/**
 * Shader of the metaballs.
 *
 * ## The mathematical idea
 *
 * Every ball emits a field in r2/d2; the sum of the fields is thresholded by a
 * narrow smoothstep, so that two balls drawing near join through a neck before
 * merging — with no code gluing them together.
 *
 * What sets this background apart from a plain threshold is the lighting: the
 * gradient of the field, obtained from two offset reads, serves as the normal.
 * A fixed light then gives a diffuse and a highlight, and the matter goes from
 * flat wash to gel. The cost is three sums instead of one, which stays bounded
 * by the number of balls.
 *
 * ## Uniforms
 *
 * - `uTime` — time in seconds, supplied by the engine.
 * - `uResolution` — canvas size in pixels, supplied by the engine.
 * - `uColorA` — the background.
 * - `uColorB` — the hue of the gel.
 * - `uColorC` — the highlight.
 * - `uPointer` — damped pointer position, in texture coordinates.
 * - `uSpeed` — speed at which the balls drift.
 * - `uCount` — number of free balls.
 * - `uThreshold` — threshold of the field.
 * - `uGloss` — strength of the highlight.
 */
export const METABALLS_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform vec2 uPointer;
uniform float uSpeed;
uniform float uCount;
uniform float uThreshold;
uniform float uGloss;

// Pseudo-random number for an index: amplified sine, fractional part.
float ballsHash(float p) {
  return fract(sin(p * 127.1) * 43758.5453123);
}

// Centre of ball i: a Lissajous curve with periods drawn from the index, never
// multiples of one another, so that the orbit never closes.
vec2 ballsCentre(float i, float t, float aspect) {
  float h1 = ballsHash(i + 1.0);
  float h2 = ballsHash(i + 11.0);
  float h3 = ballsHash(i + 23.0);
  vec2 c = vec2(
    0.5 + 0.38 * sin(t * (0.4 + h1 * 0.5) + h2 * 6.2831),
    0.5 + 0.34 * cos(t * (0.3 + h3 * 0.6) + h1 * 6.2831)
  );
  return c * vec2(aspect, 1.0);
}

// Sum of the fields: the free balls, then the pointer's one.
float ballsField(vec2 p, float t, float aspect, int count, vec2 m) {
  float total = 0.0;

  // Constant bound: the language specification demands it. Twelve balls are
  // enough; beyond that, they overlap and the pattern is lost.
  for (int i = 0; i < 12; i += 1) {
    if (i >= count) break;
    float fi = float(i);
    vec2 c = ballsCentre(fi, t, aspect);
    float r = 0.09 + 0.07 * ballsHash(fi + 41.0);
    vec2 d = p - c;
    total += r * r / max(dot(d, d), 0.0001);
  }

  vec2 dm = p - m;
  total += 0.02 / max(dot(dm, dm), 0.0001);

  return total;
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vUv * vec2(aspect, 1.0);
  vec2 m = uPointer * vec2(aspect, 1.0);
  float t = uTime * uSpeed;
  int count = int(clamp(uCount, 1.0, 12.0));

  // Three reads of the field: the value, and two offsets for the gradient.
  float e = 0.004;
  float f = ballsField(p, t, aspect, count, m);
  float fx = ballsField(p + vec2(e, 0.0), t, aspect, count, m);
  float fy = ballsField(p + vec2(0.0, e), t, aspect, count, m);

  // The matter: a narrow threshold, for a crisp edge without aliasing.
  float threshold = max(uThreshold, 0.1);
  float body = smoothstep(threshold - 0.12, threshold + 0.12, f);

  // The normal: the gradient of the field, flattened, raised by a vertical
  // component. Near the edge, the gradient dominates and the surface lies down;
  // at the core, it faces the camera. That is what makes the balls bulge.
  vec2 grad = vec2(fx - f, fy - f) / e;
  vec3 n = normalize(vec3(-grad * 0.06, 1.0));

  vec3 lightDir = normalize(vec3(-0.45, 0.55, 0.7));
  float diffuse = max(dot(n, lightDir), 0.0);
  vec3 view = vec3(0.0, 0.0, 1.0);
  vec3 h = normalize(lightDir + view);
  float highlight = pow(max(dot(n, h), 0.0), 40.0) * uGloss;

  // The edge: where the normal lies down, a lighter rim, as on a translucent
  // gel seen head-on.
  float rim = pow(1.0 - max(n.z, 0.0), 1.5) * 0.5;

  vec3 gel = uColorB * (0.55 + 0.45 * diffuse);
  gel = mix(gel, uColorC, rim);
  gel += uColorC * highlight;

  // A soft shadow under the balls, which lifts them off the background.
  float shadow = smoothstep(threshold * 0.45, threshold, f) * 0.18;
  vec3 background = uColorA * (1.0 - shadow);

  gl_FragColor = vec4(mix(background, gel, body), 1.0);
}
`

sources.component.tsx:
/**
 * Metaballs: gel balls merging, one of which follows the pointer.
 *
 * ## The principle
 *
 * A sum of fields in r2/d2, thresholded: two balls drawing near join through a
 * neck before merging. What makes the gel rather than the flat wash is the
 * gradient of the field taken as the normal — a diffuse, a highlight, a light
 * rim where the surface lies down.
 *
 * ## What this background reacts to
 *
 * To the pointer moving, with damping: one extra ball follows it and merges
 * with those it crosses. On leaving the frame, the hook brings the target back
 * to the centre — the ball returns there on its own.
 *
 * ## The pointer → shader bridge
 *
 * No React render per frame: the component mutates in place a stable array
 * passed as a uniform, and the surface re-reads its uniforms every frame. The
 * copy happens in the engine loop, at input priority.
 *
 * ## Under reduced motion
 *
 * The surface is refused by the engine and the static fallback is shown.
 *
 * @module
 */

import {
  CLOCK_PRIORITY,
  clock,
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { useEffect, useRef, useState, type ReactElement } from 'react'

import { usePointerDamped } from '@registre/hooks/usePointerDamped'

import { METABALLS_FRAGMENT } from './metaballs.shader.js'

/** What the escape hatch receives. */
export interface MetaballsControls {
  /** Colours actually handed to the shader. */
  readonly colours: readonly ShaderColour[]
  /** Reason for the refusal, if there is one. */
  readonly refused: string | undefined
}

/** Props specific to this component. */
export interface MetaballsOwnProps {
  /** Speed at which the balls drift. @defaultValue 0.3 */
  speed?: number
  /** Number of free balls. @defaultValue 7 */
  count?: number
  /** Threshold of the field. Lower means more matter. @defaultValue 1 */
  threshold?: number
  /** Strength of the highlight. @defaultValue 0.7 */
  gloss?: number
  /** Tokens whose colours are read. */
  colors?: readonly string[]
  /** Fallback classes. */
  fallback?: string
  /** Escape hatch. */
  onReady?: ReadyCallback<MetaballsControls>
}

/** All props. */
export type MetaballsProps = Customisable<MetaballsOwnProps>

/** Tokens used by default: the background, the gel, the highlight. */
const DEFAULT_TOKENS = ['--o-theme-bg', '--o-palette-brand-500', '--o-theme-fg'] as const

/** Default fallback: a frozen gradient, in the same tones. */
const DEFAULT_FALLBACK =
  'o-bg-gradient-to-br o-from-zinc-50 dark:o-from-zinc-950 o-via-brand-200 dark:o-via-brand-900 o-to-zinc-50 dark:o-to-zinc-950'

/**
 * Number of balls at low quality.
 *
 * Every ball is paid for three times — one sum for the matter, two for the
 * normal. It is the only cost lever of the shader.
 */
const LOW_COUNT = 4

/**
 * Metaballs.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Metaballs className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Metaballs({
  speed = 0.3,
  count = 7,
  threshold = 1,
  gloss = 0.7,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: MetaballsProps): ReactElement {
  const [host, setHost] = useState<HTMLDivElement | null>(null)

  // Stable array, mutated in place: the surface re-reads the uniforms every
  // frame, the identity does not change, the mutation is enough — no setState.
  const uPointer = useRef<number[]>([0.5, 0.5]).current

  const pointer = usePointerDamped({ host, speed: 3, name: 'metaballs : pointer' })

  useEffect(() => {
    const subscription = clock.subscribe(
      () => {
        // From the hook's frame (centred, y downwards) to the texture's
        // (bottom-left corner, y upwards).
        uPointer[0] = (pointer.current.x + 1) / 2
        uPointer[1] = 1 - (pointer.current.y + 1) / 2
      },
      { priority: CLOCK_PRIORITY.input, name: 'metaballs : bridge' },
    )
    return () => subscription.unsubscribe()
  }, [pointer, uPointer])

  const {
    ref,
    setHost: setShaderHost,
    ready,
    refused,
    colours,
  } = useTokenShader<HTMLDivElement>({
    fragment: METABALLS_FRAGMENT,
    colors,
    uniforms: {
      uPointer,
      uSpeed: speed,
      uCount: count,
      uThreshold: threshold,
      uGloss: gloss,
    },
    name: 'metaballs',
    // The number of balls is the only setting that weighs: it is the only bound.
    degrade: (quality) => ({
      uCount: quality === 'low' ? Math.min(count, LOW_COUNT) : count,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        setShaderHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
